#requires -Version 7.0
# YKAY Phase 1 — Production Admissions Flow
# Target requested by project owner. Change only if your local folder differs.
$ProjectRoot = "C:\Users\USER\Desktop\PROJECTS\ykay_edu\envoys-site"
$ErrorActionPreference = "Stop"

if (-not (Test-Path (Join-Path $ProjectRoot "package.json"))) {
  throw "package.json was not found at $ProjectRoot. Confirm the target path before running this script."
}

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupRoot = Join-Path $ProjectRoot "_backups\phase-1-admissions-$timestamp"

function Set-ProjectFile {
  param(
    [Parameter(Mandatory = $true)][string]$RelativePath,
    [Parameter(Mandatory = $true)][string]$Base64Content
  )

  $destination = Join-Path $ProjectRoot $RelativePath
  if (Test-Path $destination) {
    $backupPath = Join-Path $backupRoot $RelativePath
    $backupDirectory = Split-Path -Parent $backupPath
    New-Item -ItemType Directory -Force -Path $backupDirectory | Out-Null
    Copy-Item -Force $destination $backupPath
  }

  $directory = Split-Path -Parent $destination
  New-Item -ItemType Directory -Force -Path $directory | Out-Null
  [System.IO.File]::WriteAllBytes($destination, [System.Convert]::FromBase64String($Base64Content))
  Write-Host "Updated $RelativePath" -ForegroundColor Green
}

